import * as THREE from '../three.module.js';
export class BowlerActionController {
 constructor(bowler){this.bowler=bowler;this.arm='right';this.wicket='over';this.style='semi';}
 prepare(intent){const sign=this.arm==='left'?-1:1,variation=((intent.seed%101)/100-.5)*.035;return {...intent,bowlingArm:this.arm,wicketSide:this.wicket,actionStyle:this.style,releaseVariation:variation,releaseSide:sign*(this.wicket==='around'?-.82:.32)+variation,armSlot:intent.armSlot*sign,wrist:intent.wrist*sign};}
 animate(time,intent){const b=this.bowler,p=Math.min(1,time/intent.runupSeconds),left=intent.bowlingArm==='left',arm=left?2:3,other=left?3:2,sign=left?-1:1,cycle=Math.sin(time*(intent.spin?8:13));const bound=THREE.MathUtils.clamp((p-.58)/.20,0,1),travel=p<.78?Math.pow(p/.78,1.2)*.84:.84+(p-.78)/.22*.16;b.deliveryPhase=p<.12?'start':p<.55?'accelerate':p<.66?'gather':p<.78?'bound':p<.86?'back-foot contact':p<.97?'front-foot contact':'release';b.g.position.set(intent.releaseSide,Math.sin(bound*Math.PI)*.12,THREE.MathUtils.lerp(intent.spin?-22.5:-27.5,-18.3,travel));b.g.rotation.set(0,0,0);b.limbs[0].rotation.x=cycle*.5;b.limbs[1].rotation.x=-cycle*.5;b.limbs[2].rotation.set(-cycle*.65,0,0);b.limbs[3].rotation.set(cycle*.65,0,0);const a=THREE.MathUtils.clamp((p-.68)/.32,0,1),turn={front:.08,semi:.42,side:.82}[intent.actionStyle]??.42;b.torso.rotation.y=sign*turn*Math.sin(a*Math.PI);if(p>.68){b.limbs[arm].rotation.x=-Math.PI*a;b.limbs[arm].rotation.z=intent.armSlot*a;b.hands[arm-2].rotation.y=intent.wrist*a;b.limbs[other].rotation.x=-Math.PI*.7*(1-a);b.g.rotation.z=sign*Math.sin(a*Math.PI)*.09;b.limbs[0].rotation.x=-.5*(1-a);b.limbs[1].rotation.x=.28*Math.sin(a*Math.PI);b.torso.rotation.x=-Math.sin(a*Math.PI)*.1;}b.hand=b.hands[arm-2];b.g.updateMatrixWorld(true);}
}
